frappe.ui.form.on("Item", {
    item_name: function(frm) {
        if (frm.doc.item_name && !frm.doc.item_code) {  // Generate only if item_code is empty
            generateUniqueItemCode(frm);
        }
    }
});

function generateUniqueItemCode(frm) {
    // Generate a random 3-digit number
    const randomNumber = Math.floor(100 + Math.random() * 900); // 3-digit number (100-999)

    // Create a base item_code using item_name and random number
    const baseCode = `${frm.doc.item_name.replace(/[^a-zA-Z0-9]/g, '').substring(0, 10).toUpperCase()}${randomNumber}`;

    // Check if the generated code is unique
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Item",
            filters: [["item_code", "=", baseCode]],  // Check if this code already exists
            fields: ["item_code"],
            limit: 1
        },
        callback: function(r) {
            if (r.message && r.message.length) {
                // If the code already exists, recursively generate a new one
                generateUniqueItemCode(frm);
            } else {
                // If unique, set the item_code
                frm.set_value("item_code", baseCode);
            }
        }
    });
}

