frappe.ui.form.on('Sales Invoice', {
    onload: function (frm) {
        // Set default value for custom_payment_due_days to 30
        if (!frm.doc.custom_payment_due_days) {
            // frm.set_value('custom_payment_due_days', '30');
        }

        // Calculate custom_payment_due_date when the form loads
        if (frm.doc.custom_payment_due_days && frm.doc.posting_date) {
            calculate_due_date_directly(frm);
        }
    },

    custom_payment_due_days: function (frm) {
        // Recalculate custom_payment_due_date whenever custom_payment_due_days is changed
        calculate_due_date_directly(frm);
    },

    posting_date: function (frm) {
        // Recalculate custom_payment_due_date whenever posting_date is changed
        calculate_due_date_directly(frm);
    }
});

function calculate_due_date_directly(frm) {
    const payment_due_days = frm.doc.custom_payment_due_days;
    const posting_date = frm.doc.posting_date;

    if (!posting_date) {
        frappe.msgprint(__('Please set the Posting Date first.'));
        frm.set_value('custom_payment_due_date', null);
        return;
    }

    if (payment_due_days === 'COD') {
        // Set due_date to the same as posting_date for COD
        frm.set_value('custom_payment_due_date', posting_date);
    } else if (!isNaN(payment_due_days)) {
        // Add specified days to the posting date
        const postingDate = new Date(posting_date);
        postingDate.setDate(postingDate.getDate() + parseInt(payment_due_days)); // Add days
        const dueDate = postingDate.toISOString().split('T')[0]; // Format as YYYY-MM-DD
        frm.set_value('custom_payment_due_date', dueDate);
    } else {
        // Handle invalid or missing values
        frappe.msgprint(__('Please select a valid payment due period.'));
        frm.set_value('custom_payment_due_date', null);
    }
}

