    item_code: function (frm, cdt, cdn) {
        let item_row = frappe.get_doc(cdt, cdn);
        let other_plan = item_row.item_code === "BASICPLAN288" ? "STANDARD301" : "BASICPLAN288";

        // Check if the other plan already exists in the list
        let duplicate_plan = frm.doc.items.some(row => row.item_code === other_plan);

        if (duplicate_plan) {
            frappe.msgprint({
                title: __('Validation Error'),
                message: __('You cannot select both Basic Plan and Standard Plan in the same transaction.'),
                indicator: 'red'
            });

            frappe.model.set_value(cdt, cdn, 'item_code', null); // Reset the field
