frappe.ui.form.on('Sales Invoice', {
    before_cancel: function(frm) {
        console.log("Checking cancellation logic based on posting date only");

        // Ensure posting_date is available
        if (frm.doc.posting_date) {
            console.log("Posting Date:", frm.doc.posting_date);

            var posting_date = frappe.datetime.str_to_obj(frm.doc.posting_date); // Convert posting date to Date object
            var current_date = frappe.datetime.str_to_obj(frappe.datetime.nowdate()); // Get current date as Date object

            console.log("Posting Date (Object):", posting_date);
            console.log("Current Date (Object):", current_date);

            // Calculate the difference in days
            var day_difference = frappe.datetime.get_day_diff(frappe.datetime.nowdate(), frm.doc.posting_date);
            console.log("Day Difference:", day_difference);

            // Check if the difference is greater than 3 days (72 hours)
            if (day_difference > 3 || day_difference < 0) {
                console.log("Cancellation Denied: Date difference exceeded 3 days.");
                frappe.msgprint(__('This invoice was posted over 3 days ago and cannot be canceled as per company policy.'));
                frappe.validated = false;
            } else {
                console.log("Cancellation Allowed: Within 3 days.");
            }
        } else {
            console.log("Error: Posting date not set.");
            frappe.msgprint(__('The posting date for this invoice is not set. Please set the posting date to proceed.'));
            frappe.validated = false;
        }
    }
});

