frappe.ui.form.on("Company", {
    validate: function(frm) {
        if (frm.doc.custom_contact_number && !frm.doc.custom_contact_number.match(/^\+60\d{7,12}$/)) {
            frappe.throw("Only Malaysian phone numbers (+60) are allowed.");
        }
    }
});

frappe.ui.form.on('Quotation', {
    customer: function(frm) {
        if (frm.doc.customer) {
            frappe.db.get_value('Customer', frm.doc.customer, 'customer_type')
                .then(r => {
                    if (r.message && r.message.buyer_type) {
                        frm.set_value('custom_buyer_type', r.message.buyer_type);
                    } else {
                        frm.set_value('custom_buyer_type', '');
                    }
                });
        } else {
            frm.set_value('custom_buyer_type', '');
        }
    }
});

frappe.ui.form.on('Journal Entry', {
    onload: function(frm) {
        // Wait for table to load
        setTimeout(() => {
            $('.grid-custom-buttons .btn[data-action="configure-columns"]').hide();
        }, 500);
    }
});
